<?php require __DIR__.'/../includes/bootstrap.php'; admin_required();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=$_POST['type']??'despesa';if(in_array($type,['receita','despesa'],true)){db()->prepare('INSERT INTO finance_transactions(type,category,description,amount,due_date,paid_date,status,payment_method,notes) VALUES (?,?,?,?,?,?,?,?,?)')->execute([$type,trim($_POST['category']),trim($_POST['description']),(float)str_replace(',','.',$_POST['amount']),$_POST['due_date']?:null,$_POST['status']==='pago'?($_POST['paid_date']?:date('Y-m-d')):null,$_POST['status'],trim($_POST['payment_method'])?:null,trim($_POST['notes'])?:null]);flash('ok','Lançamento registrado.');}header('Location: finance.php?month='.urlencode($_GET['month']??date('Y-m')));exit;}
$month=$_GET['month']??date('Y-m');$st=db()->prepare("SELECT * FROM finance_transactions WHERE DATE_FORMAT(COALESCE(paid_date,due_date,created_at),'%Y-%m')=? ORDER BY COALESCE(paid_date,due_date,DATE(created_at)) DESC,id DESC");$st->execute([$month]);$items=$st->fetchAll();$income=0;$expense=0;foreach($items as $i){if($i['status']==='pago'){if($i['type']==='receita')$income+=(float)$i['amount'];else$expense+=(float)$i['amount'];}}$msg=flash('ok');
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Financeiro | PG Estética</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="admin-shell"><?php include '_nav.php'; ?><section><div class="container"><div class="admin-heading"><div><span class="eyebrow">controle financeiro</span><h1>Financeiro</h1></div><form method="get" class="inline-form"><input type="month" name="month" value="<?= e($month) ?>"><button class="btn btn-outline">Filtrar</button></form></div><?php if($msg): ?><div class="notice"><?= e($msg) ?></div><?php endif; ?><div class="stat-grid"><div class="stat"><span>Receitas pagas</span><strong class="money-stat"><?= money($income) ?></strong></div><div class="stat"><span>Despesas pagas</span><strong class="money-stat"><?= money($expense) ?></strong></div><div class="stat"><span>Resultado</span><strong class="money-stat"><?= money($income-$expense) ?></strong></div></div><div class="two-col"><div class="panel"><h2>Novo lançamento</h2><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><div class="row"><div><label>Tipo</label><select name="type"><option value="receita">Receita</option><option value="despesa">Despesa</option></select></div><div><label>Categoria</label><input name="category" required placeholder="Procedimentos, aluguel..."></div></div><label>Descrição</label><input name="description" required><div class="row"><div><label>Valor</label><input name="amount" inputmode="decimal" required></div><div><label>Vencimento</label><input type="date" name="due_date"></div></div><div class="row"><div><label>Status</label><select name="status"><option value="pendente">Pendente</option><option value="pago">Pago</option><option value="cancelado">Cancelado</option></select></div><div><label>Data de pagamento</label><input type="date" name="paid_date"></div></div><label>Forma de pagamento</label><input name="payment_method"><label>Observações</label><textarea name="notes"></textarea><button class="btn btn-primary">Salvar lançamento</button></form></div><div class="panel"><h2>Movimentações</h2><div class="table-wrap flat"><table><thead><tr><th>Data</th><th>Descrição</th><th>Status</th><th>Valor</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= e($i['paid_date']?:$i['due_date']?:substr($i['created_at'],0,10)) ?></td><td><strong><?= e($i['description']) ?></strong><br><span class="small muted"><?= e($i['category']) ?> · <?= e($i['payment_method']) ?></span></td><td><?= e($i['status']) ?></td><td class="<?= $i['type']==='receita'?'positive':'negative' ?>"><?= $i['type']==='receita'?'+':'-' ?> <?= money((float)$i['amount']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></div></section></body></html>
